package net.officefloor.hq.app.history;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.person.Hold;
import org.springframework.jdbc.core.RowCallbackHandler;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The sheet's history (see V48__history.sql): each change that a statement taken as of a past date
 *  depends on, kept with the sheet's today when it was made. The repositories that make these changes
 *  record them here, in the same transaction. */
@Repository
public class HistoryRepository {

    /** The sheet's today, for the on_date of a change. */
    private static final String TODAY = "(SELECT s.today FROM sheet s WHERE s.id = ?)";

    private final JdbcTemplate jdbc;

    public HistoryRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Keep a claim's values as they are now, after a change to it. */
    public void claim(String sheetId, long claimId) {
        jdbc.update("INSERT INTO claim_history (sheet_id, on_date, claim_id, person_id, amount, claim_date, status,"
                + " settled_due, stated, stated_due, stated_na, corrects, due_by, deferred_until)"
                + " SELECT c.sheet_id, s.today, c.id, c.person_id, c.amount, c.claim_date, c.status, c.settled_due,"
                + " c.stated, c.stated_due, c.stated_na, c.corrects, c.due_by, c.deferred_until"
                + " FROM claim c JOIN sheet s ON s.id = c.sheet_id WHERE c.id = ? AND c.sheet_id = ?", claimId, sheetId);
    }

    /** Keep a rate set for a grade from a from-date (null: from the beginning of time). */
    public void rate(String sheetId, String grade, BigDecimal pct, LocalDate from, LocalDate to) {
        jdbc.update("INSERT INTO rate_history (sheet_id, on_date, grade, pct, from_date, to_date) VALUES (?, " + TODAY
                + ", ?, ?, ?, ?)", sheetId, sheetId, grade, pct, date(from), date(to));
    }

    /** Keep a grade given to a person from a from-date (null: from the beginning of time). */
    public void grade(String sheetId, long personId, String grade, LocalDate from) {
        jdbc.update("INSERT INTO grade_history (sheet_id, on_date, person_id, grade, from_date) VALUES (?, " + TODAY
                + ", ?, ?, ?)", sheetId, sheetId, personId, grade, date(from));
    }

    /** Keep a dated setting's value recorded from a from-date (null: blank). */
    public void setting(String sheetId, String key, LocalDate from, String value) {
        jdbc.update("INSERT INTO setting_history (sheet_id, on_date, setting_key, from_date, setting) VALUES (?, " + TODAY
                + ", ?, ?, ?)", sheetId, sheetId, key, date(from), value);
    }

    /** Keep the sheet's policy date set (null: blank). */
    public void policy(String sheetId, LocalDate policyDate) {
        jdbc.update("INSERT INTO policy_history (sheet_id, on_date, policy_date) VALUES (?, " + TODAY + ", ?)",
                sheetId, sheetId, date(policyDate));
    }

    /** Keep a person's retirement from a date. */
    public void retire(String sheetId, long personId, LocalDate from) {
        jdbc.update("INSERT INTO retire_history (sheet_id, on_date, person_id, retired_from) VALUES (?, " + TODAY
                + ", ?, ?)", sheetId, sheetId, personId, date(from));
    }

    private static Date date(LocalDate d) {
        return d == null ? null : Date.valueOf(d);
    }

    /** Whether the person was on the sheet at the end of a day: added while the sheet's today was on or before it. */
    public boolean existed(String sheetId, long personId, LocalDate day) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM person WHERE sheet_id = ? AND id = ? AND added_on <= ?",
                Integer.class, sheetId, personId, Date.valueOf(day));
        return n != null && n > 0;
    }

    /** The sheet as it stood at the end of a day: the changes made while its today was on or before that day,
     *  each kept value the last of them (in the order made). */
    public SheetAsOf asOf(String sheetId, LocalDate day) {
        Date on = Date.valueOf(day);
        Map<Long, Claim> claims = new LinkedHashMap<>();
        jdbc.query("SELECT h.* FROM claim_history h WHERE h.sheet_id = ? AND h.id = (SELECT MAX(l.id) FROM claim_history l"
                + " WHERE l.sheet_id = h.sheet_id AND l.claim_id = h.claim_id AND l.on_date <= ?) ORDER BY h.claim_id",
                (RowCallbackHandler) rs -> {
                    String status = rs.getString("status");
                    LocalDate deferredUntil = local(rs.getDate("deferred_until"));
                    BigDecimal settled = rs.getBigDecimal("settled_due");
                    BigDecimal stated = rs.getBigDecimal("stated_due");
                    claims.put(rs.getLong("claim_id"), new Claim(rs.getLong("claim_id"), rs.getLong("person_id"),
                            rs.getBigDecimal("amount").setScale(2).toPlainString(), local(rs.getDate("claim_date")).toString(),
                            "", status, null, settled == null ? null : settled.setScale(2).toPlainString(), null,
                            rs.getBoolean("stated"), stated == null ? null : stated.setScale(2).toPlainString(),
                            rs.getString("corrects"), local(rs.getDate("due_by")).toString(), rs.getBoolean("stated_na"),
                            deferredUntil == null ? null : deferredUntil.toString(),
                            status.equals("OPEN") && deferredUntil != null && deferredUntil.isAfter(day), 0, null, false));
                }, sheetId, on);
        Map<Long, TreeMap<LocalDate, String>> grades = new HashMap<>();
        jdbc.query("SELECT person_id, grade, from_date FROM grade_history WHERE sheet_id = ? AND on_date <= ? ORDER BY id",
                (RowCallbackHandler) rs -> grades.computeIfAbsent(rs.getLong("person_id"), k -> new TreeMap<>())
                        .put(from(rs.getDate("from_date")), rs.getString("grade")), sheetId, on);
        Map<String, TreeMap<LocalDate, SheetAsOf.Rate>> rates = new HashMap<>();
        jdbc.query("SELECT grade, pct, from_date, to_date FROM rate_history WHERE sheet_id = ? AND on_date <= ? ORDER BY id",
                (RowCallbackHandler) rs -> rates.computeIfAbsent(rs.getString("grade"), k -> new TreeMap<>())
                        .put(from(rs.getDate("from_date")), new SheetAsOf.Rate(rs.getBigDecimal("pct"), local(rs.getDate("to_date")))),
                sheetId, on);
        Map<String, TreeMap<LocalDate, String>> settings = new HashMap<>();
        jdbc.query("SELECT setting_key, from_date, setting FROM setting_history WHERE sheet_id = ? AND on_date <= ? ORDER BY id",
                (RowCallbackHandler) rs -> settings.computeIfAbsent(rs.getString("setting_key"), k -> new TreeMap<>())
                        .put(from(rs.getDate("from_date")), rs.getString("setting")), sheetId, on);
        List<Date> policy = jdbc.query("SELECT policy_date FROM policy_history WHERE sheet_id = ? AND on_date <= ?"
                + " ORDER BY id DESC LIMIT 1", (rs, i) -> rs.getDate("policy_date"), sheetId, on);
        Map<Long, List<Hold>> holds = new HashMap<>();
        jdbc.query("SELECT person_id, from_date, to_date FROM person_hold WHERE sheet_id = ? AND held_on <= ? ORDER BY id",
                (RowCallbackHandler) rs -> holds.computeIfAbsent(rs.getLong("person_id"), k -> new ArrayList<>())
                        .add(new Hold(text(rs.getDate("from_date")), text(rs.getDate("to_date")))), sheetId, on);
        Map<Long, String> retired = new HashMap<>();
        jdbc.query("SELECT person_id, retired_from FROM retire_history WHERE sheet_id = ? AND on_date <= ? ORDER BY id",
                (RowCallbackHandler) rs -> retired.put(rs.getLong("person_id"), text(rs.getDate("retired_from"))), sheetId, on);
        return new SheetAsOf(day, claims, grades, rates, settings, policy.isEmpty() ? null : local(policy.get(0)), holds,
                retired, c -> {
                    List<Date> found = jdbc.queryForList("SELECT claim_date FROM claim WHERE sheet_id = ? AND person_id = ?"
                            + " AND claim_no = ? ORDER BY id LIMIT 1", Date.class, sheetId, c.personId(), c.corrects());
                    return found.isEmpty() ? null : found.get(0).toLocalDate().toString();
                });
    }

    private static LocalDate local(Date d) {
        return d == null ? null : d.toLocalDate();
    }

    private static String text(Date d) {
        return d == null ? null : d.toLocalDate().toString();
    }

    /** A from-date as a key: a null one is the beginning of time. */
    private static LocalDate from(Date d) {
        return d == null ? SheetAsOf.BEGINNING : d.toLocalDate();
    }
}
package net.officefloor.hq.app.history;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.function.Function;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.person.Hold;

/** A sheet as it stood at the end of a day: what the changes made while the sheet's today was on or
 *  before that day left (see {@link HistoryRepository#asOf}). The day stands in for the sheet's today in
 *  every figure, worked out by the same rules as the live ones in ClaimRepository: the grade and rate in
 *  force, the rounding, the floor, late charges, holds and retirements.
 *
 *  @param claims        each claim's values then, by claim id (a claim added later is absent)
 *  @param grades        each person's grades then, by person id, each by from-date (null: from the beginning of time)
 *  @param rates         each grade's rates then, by grade, each by from-date
 *  @param settings      each dated setting's values then, by key, each by from-date
 *  @param policyDate    the policy date then (null: blank, the day itself)
 *  @param holds         each person's holds then, by person id
 *  @param retiredFrom   the date each person was retired from then, by person id (absent: not retired)
 *  @param correctedDate the date of a person's claim with a number (person id, number), for a correction's rounding
 */
public record SheetAsOf(LocalDate day, Map<Long, Claim> claims, Map<Long, TreeMap<LocalDate, String>> grades,
        Map<String, TreeMap<LocalDate, Rate>> rates, Map<String, TreeMap<LocalDate, String>> settings,
        LocalDate policyDate, Map<Long, List<Hold>> holds, Map<Long, String> retiredFrom,
        Function<Claim, String> correctedDate) {

    /** A rate then: its percent and to-date (null: with no end). */
    public record Rate(BigDecimal pct, LocalDate to) {
    }

    /** The minimum date, standing for "from the beginning of time" (a null from-date). */
    public static final LocalDate BEGINNING = LocalDate.of(1, 1, 1);

    /** A person's claims then, newest first. */
    public List<Claim> claimsOf(long personId) {
        List<Claim> mine = new ArrayList<>();
        for (Claim c : claims.values()) {
            if (c.personId() == personId) mine.add(c);
        }
        mine.sort((a, b) -> Long.compare(b.id(), a.id()));
        return mine;
    }

    /** A person's holds as they acted on live totals then: once their retirement date was reached they are
     *  held over every date as well. */
    public List<Hold> liveHolds(long personId) {
        List<Hold> all = new ArrayList<>(holds.getOrDefault(personId, List.of()));
        String retired = retiredFrom.get(personId);
        if (retired != null && retired.compareTo(day.toString()) <= 0) all.add(new Hold(null, null));
        return all;
    }

    private static <V> V latest(TreeMap<LocalDate, V> dated, LocalDate on) {
        if (dated == null) return null;
        Map.Entry<LocalDate, V> e = dated.floorEntry(on);
        return e == null ? null : e.getValue();
    }

    /** The grade a person had then on a date. */
    public String gradeOn(long personId, LocalDate on) {
        return latest(grades.get(personId), on);
    }

    /** The rate that would apply then to a person on a date; null when there is none. */
    private Rate rateOn(long personId, LocalDate on) {
        String grade = gradeOn(personId, on);
        return grade == null ? null : latest(rates.get(grade), on);
    }

    /** A dated setting's value then on a date: a list holding the value (null when blank), empty when none was recorded. */
    private List<String> setting(String key, LocalDate on) {
        TreeMap<LocalDate, String> dated = settings.get(key);
        if (dated == null) return List.of();
        Map.Entry<LocalDate, String> e = dated.floorEntry(on);
        if (e == null) return List.of();
        List<String> found = new ArrayList<>();
        found.add(e.getValue());
        return found;
    }

    /** The floor then on a date; 1.00 before any was recorded. */
    public BigDecimal floor(LocalDate on) {
        List<String> found = setting("floor", on);
        return found.isEmpty() || found.get(0) == null ? BigDecimal.ONE.setScale(2) : new BigDecimal(found.get(0)).setScale(2);
    }

    /** The late percent then on a date; 0.00 before any was recorded. */
    public BigDecimal latePct(LocalDate on) {
        List<String> found = setting("late-pct", on);
        return found.isEmpty() || found.get(0) == null ? BigDecimal.ZERO.setScale(2) : new BigDecimal(found.get(0)).setScale(2);
    }

    /** The cap in force on the day; null when there was none. */
    public BigDecimal cap() {
        List<String> found = setting("cap", day);
        return found.isEmpty() || found.get(0) == null ? null : new BigDecimal(found.get(0));
    }

    /** A claim's rate figure then, not floored; null when no rate applied. */
    public BigDecimal due(Claim claim) {
        LocalDate date = LocalDate.parse(claim.date());
        Rate rate = rateOn(claim.personId(), date);
        if (rate == null || (rate.to() != null && rate.to().isBefore(date))) return null;
        return new BigDecimal(claim.amount()).multiply(rate.pct()).movePointLeft(2).setScale(2, rounding(claim));
    }

    /** How a claim's figures rounded then: half up when dated before the policy date (blank: the day), else
     *  half to even; a correction by the date of the claim it corrects. */
    private RoundingMode rounding(Claim claim) {
        String date = claim.date();
        if (claim.corrects() != null) {
            String corrected = correctedDate.apply(claim);
            if (corrected != null) date = corrected;
        }
        LocalDate policy = policyDate != null ? policyDate : day;
        return LocalDate.parse(date).isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** A claim's figure then: its settled due, else the one a statement bound it to (none when bound to
     *  n/a), else its rate figure; null when it had none. */
    public BigDecimal figure(Claim claim) {
        if (claim.due() != null) return new BigDecimal(claim.due());
        if (claim.bound() && claim.statedNa()) return null;
        if (claim.bound() && claim.statedDue() != null) return new BigDecimal(claim.statedDue());
        return due(claim);
    }

    /** A claim's due then: its settled due, else its figure plus its late charges on the day, at least the
     *  floor (a correction has neither); null when it had no figure. */
    public BigDecimal dueNow(Claim claim) {
        if (claim.due() != null) return new BigDecimal(claim.due());
        BigDecimal figure = figure(claim);
        if (figure == null || new BigDecimal(claim.amount()).signum() < 0) return figure;
        BigDecimal due = figure.add(lateCharge(claim, figure));
        return due.max(floor(LocalDate.parse(claim.date())));
    }

    private BigDecimal lateCharge(Claim claim, BigDecimal figure) {
        BigDecimal charge = BigDecimal.ZERO.setScale(2);
        if (!claim.open() || claim.deferred()) return charge;
        LocalDate dueBy = LocalDate.parse(claim.dueBy());
        long periods = dueBy.isBefore(day) ? ChronoUnit.DAYS.between(dueBy, day) / 30 : 0;
        RoundingMode rounding = rounding(claim);
        for (long n = 1; n <= periods; n++) {
            BigDecimal pct = latePct(dueBy.plusDays(30 * n));
            if (pct.signum() == 0) continue;
            charge = charge.add(figure.multiply(pct).movePointLeft(2).setScale(2, rounding));
        }
        return charge;
    }

    /** Whether the rate that would apply to a claim then had ended before its date. */
    public boolean rateEnded(Claim claim) {
        LocalDate date = LocalDate.parse(claim.date());
        Rate rate = rateOn(claim.personId(), date);
        return rate != null && rate.to() != null && rate.to().isBefore(date);
    }

    /** Whether a rate for the grade a person had on the day was in force on it. */
    public boolean rated(long personId) {
        Rate rate = rateOn(personId, day);
        return rate != null && (rate.to() == null || !rate.to().isBefore(day));
    }
}
-- The sheet's history, for a statement taken as of a past date: each change is kept with the sheet's
-- today when it was made (on_date), in the order made (id). The state as of the end of a date is what
-- the changes made while the sheet's today was on or before it left. What was there before this
-- history was kept counts from the beginning of time (0001-01-01).

-- A person counts from the sheet's today when they were added.
ALTER TABLE person ADD COLUMN added_on DATE DEFAULT DATE '0001-01-01' NOT NULL;

-- A hold counts from the sheet's today when it was given.
ALTER TABLE person_hold ADD COLUMN held_on DATE DEFAULT DATE '0001-01-01' NOT NULL;

-- A claim's values after each change to it (the ones its figures and statement binding depend on).
CREATE TABLE claim_history (
    id             BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id       VARCHAR(200)   NOT NULL REFERENCES sheet (id),
    on_date        DATE           NOT NULL,
    claim_id       BIGINT         NOT NULL,
    person_id      BIGINT         NOT NULL,
    amount         DECIMAL(14, 2) NOT NULL,
    claim_date     DATE           NOT NULL,
    status         VARCHAR(10)    NOT NULL,
    settled_due    DECIMAL(19, 2),
    stated         BOOLEAN        NOT NULL,
    stated_due     DECIMAL(19, 2),
    stated_na      BOOLEAN        NOT NULL,
    corrects       VARCHAR(600),
    due_by         DATE           NOT NULL,
    deferred_until DATE
);
CREATE INDEX claim_history_sheet ON claim_history (sheet_id, claim_id, id);
INSERT INTO claim_history (sheet_id, on_date, claim_id, person_id, amount, claim_date, status, settled_due, stated,
        stated_due, stated_na, corrects, due_by, deferred_until)
    SELECT sheet_id, DATE '0001-01-01', id, person_id, amount, claim_date, status, settled_due, stated, stated_due,
        stated_na, corrects, due_by, deferred_until FROM claim ORDER BY id;

-- Each rate set: it replaces the grade's rate from the same from-date.
CREATE TABLE rate_history (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200)  NOT NULL REFERENCES sheet (id),
    on_date   DATE          NOT NULL,
    grade     VARCHAR(1)    NOT NULL,
    pct       DECIMAL(7, 2) NOT NULL,
    from_date DATE,
    to_date   DATE
);
CREATE INDEX rate_history_sheet ON rate_history (sheet_id, id);
INSERT INTO rate_history (sheet_id, on_date, grade, pct, from_date, to_date)
    SELECT sheet_id, DATE '0001-01-01', grade, pct, from_date, to_date FROM rate;

-- Each grade given to a person: it replaces the one they had from the same from-date.
CREATE TABLE grade_history (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    on_date   DATE         NOT NULL,
    person_id BIGINT       NOT NULL,
    grade     VARCHAR(1)   NOT NULL,
    from_date DATE
);
CREATE INDEX grade_history_sheet ON grade_history (sheet_id, person_id, id);
INSERT INTO grade_history (sheet_id, on_date, person_id, grade, from_date)
    SELECT sheet_id, DATE '0001-01-01', person_id, grade, from_date FROM person_grade;

-- Each dated setting value recorded: it replaces the one recorded from the same from-date.
CREATE TABLE setting_history (
    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id    VARCHAR(200) NOT NULL REFERENCES sheet (id),
    on_date     DATE         NOT NULL,
    setting_key VARCHAR(20)  NOT NULL,
    from_date   DATE         NOT NULL,
    setting     VARCHAR(20)
);
CREATE INDEX setting_history_sheet ON setting_history (sheet_id, id);
INSERT INTO setting_history (sheet_id, on_date, setting_key, from_date, setting)
    SELECT sheet_id, DATE '0001-01-01', setting_key, from_date, setting FROM setting_value;

-- Each policy date set (null: blank, the sheet's today).
CREATE TABLE policy_history (
    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id    VARCHAR(200) NOT NULL REFERENCES sheet (id),
    on_date     DATE         NOT NULL,
    policy_date DATE
);
INSERT INTO policy_history (sheet_id, on_date, policy_date)
    SELECT id, DATE '0001-01-01', policy_date FROM sheet WHERE policy_date IS NOT NULL;

-- Each retirement of a person.
CREATE TABLE retire_history (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(200) NOT NULL REFERENCES sheet (id),
    on_date      DATE         NOT NULL,
    person_id    BIGINT       NOT NULL,
    retired_from DATE         NOT NULL
);
INSERT INTO retire_history (sheet_id, on_date, person_id, retired_from)
    SELECT sheet_id, DATE '0001-01-01', id, retired_from FROM person WHERE retired_from IS NOT NULL;
