package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateToday {
    public void validate(@RequestBody TodayRequest request, Out<LocalDate> today) throws BadRequestException {
        String raw = request == null || request.date() == null ? "" : request.date().trim();
        if (raw.isEmpty()) {
            throw new BadRequestException("date is required");
        }
        try {
            today.set(LocalDate.parse(raw));
        } catch (DateTimeParseException e) {
            throw new BadRequestException("date must be yyyy-mm-dd");
        }
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.period.PeriodCloser;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

/** Set the sheet's today (a new date releases every claim's editor lock), then close each open period lapsed past the sheet's grace days. */
public class SaveSheetToday {
    public void save(@PathVariable("sheetId") String sheetId, @Val LocalDate today,
            ServerHttpConnection connection, SheetRepository repository, Rollup rollup, PeriodCloser closer, ClaimRepository claims,
            Out<Sheet> sheet)
            throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        Rollup.Snapshot before = rollup.take(id);
        LocalDate was = repository.today(id);
        if (!repository.setToday(id, today)) {
            throw new BadRequestException("no such sheet");
        }
        if (!today.equals(was)) {
            claims.unlockAll(id);
        }
        closer.closeLapsed(id, by, today);
        rollup.record(id, by, before);
        sheet.set(new Sheet(id, today.toString(), repository.archived(id)));
    }
}
package net.officefloor.hq.app.sheet;

import java.sql.Date;
import java.time.LocalDate;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class SheetRepository {

    private final JdbcTemplate jdbc;

    public SheetRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet with this id, made empty (its today the real date) when the id was never used. */
    public Sheet loadOrCreate(String id, String user) {
        Integer known = jdbc.queryForObject("SELECT COUNT(*) FROM sheet WHERE id = ?", Integer.class, id);
        if (known == null || known == 0) {
            try {
                jdbc.update("INSERT INTO sheet (id, created_by, today) VALUES (?, ?, ?)", id, user,
                        Date.valueOf(LocalDate.now()));
            } catch (DuplicateKeyException made) {
                // another user loaded the same new id at the same moment: it is made either way
            }
        }
        return new Sheet(id, today(id).toString(), archived(id));
    }

    /** The sheet's today: the date every date decision and default in the sheet uses. */
    public LocalDate today(String id) {
        Date today = jdbc.queryForObject("SELECT today FROM sheet WHERE id = ?", Date.class, id);
        return today.toLocalDate();
    }

    /** Whether a steward has archived the sheet. */
    public boolean archived(String id) {
        Boolean archived = jdbc.queryForObject("SELECT archived FROM sheet WHERE id = ?", Boolean.class, id);
        return Boolean.TRUE.equals(archived);
    }

    /** Archive the sheet; false when there is no such sheet. */
    public boolean archive(String id) {
        return jdbc.update("UPDATE sheet SET archived = TRUE WHERE id = ?", id) > 0;
    }

    /** Set the sheet's today; false when there is no such sheet. */
    public boolean setToday(String id, LocalDate today) {
        return jdbc.update("UPDATE sheet SET today = ? WHERE id = ?", Date.valueOf(today), id) > 0;
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.Set;
import net.officefloor.hq.app.settings.SettingsRepository;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    /** The lines that only report figures (or tell of a change already recorded): never marked for a delegator. */
    private static final Set<String> REPORTS = Set.of("ROLLUP", "TOTALS", "ALERT", "NOTIFY");

    private final Path file;

    private final ObjectProvider<SettingsRepository> settings;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, ObjectProvider<SettingsRepository> settings) {
        this.file = Path.of(path);
        this.settings = settings;
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. A change made by a user acting
     *  under a delegation of the steward role (one covering the sheet's today) ends with for=<the steward
     *  who delegated>. */
    public synchronized void record(String entry) {
        entry = entry + delegatedFor(entry);
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** " for=<steward>" when the record (EVENT sheet=<id> by=<user> ...) is a change by a delegated user. */
    private String delegatedFor(String entry) {
        String[] parts = entry.split(" ", 4);
        if (parts.length < 3 || REPORTS.contains(parts[0]) || !parts[1].startsWith("sheet=") || !parts[2].startsWith("by=")) {
            return "";
        }
        String delegator = settings.getObject().delegator(parts[1].substring("sheet=".length()), parts[2].substring("by=".length()));
        return delegator == null ? "" : " for=" + delegator;
    }

    /** Remove the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
# Change the sheet's today: the date every date decision and default date in the sheet uses.
guard:
  class: net.officefloor.hq.app.settings.RefuseViewer
  next: validate
validate:
  class: net.officefloor.hq.app.sheet.ValidateToday
  next: save
save:
  class: net.officefloor.hq.app.sheet.SaveSheetToday
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithSheet
# Load a sheet by id: made (empty) the first time the id is used, re-read from the store after.
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithSheet

