import { createFileRoute } from '@tanstack/react-router';
import { CurrentUser, SignIn } from '../features/session/SignIn';
import { useActiveSheet, useSignedInUser } from '../features/session/useSession';
import { SheetPicker } from '../features/sheet/SheetPicker';
import { SheetBody } from '../slots/defs/sheetBody';

// The one screen. Sign in first; then choose a sheet; the sheet's own features fill SheetBody.
export const Route = createFileRoute('/')({
  component: Home,
});

function Home() {
  const [user] = useSignedInUser();
  const [sheetId] = useActiveSheet();
  if (!user) return <SignIn />;
  return (
    <>
      <CurrentUser />
      <SheetPicker />
      {sheetId && (
        <section data-testid="sheet-body" key={sheetId}>
          <SheetBody.Slot sheetId={sheetId} user={user} />
        </section>
      )}
    </>
  );
}
import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
  contributions.push(entry);
}

export function forSlot(id: string): Registered[] {
  return contributions
    .filter((c) => c.slot === id)
    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
}
import { SheetBody } from '../../slots/defs/sheetBody';
import { useClaims } from '../claims/useClaims';
import { useOverdue } from '../overdue/useOverdue';
import { usePeople } from '../people/usePeople';
import { useDueTotals } from '../rates/useDueTotals';
import { trimmedSum } from '../rates/useRates';
import { countWithStatus, STATUSES } from '../summary/statusCounts';

/** The sheet's header counters, shown at all times: how many people are on the sheet (retired people
 *  included), how many claims have each status (as the summary counts them), and the sheet's
 *  due-total and overdue-total (as the totals show them, trimmed). */
function Header({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const dueTotals = useDueTotals(sheetId);
  const overdue = [...useOverdue(sheetId).values()];
  return (
    <header data-testid="header">
      People <strong data-testid="header-people-count">{(people.data ?? []).length}</strong>
      {STATUSES.map((s) => (
        <span key={s}>
          {' '}
          · {s} <strong data-testid={`header-claims-${s}-count`}>{countWithStatus(claims.data, s)}</strong>
        </span>
      ))}{' '}
      · Due total <strong data-testid="header-due-total">{trimmedSum([...dueTotals.values()])}</strong> · Overdue
      total <strong data-testid="header-overdue-total">{trimmedSum(overdue.map((f) => f.total))}</strong>
    </header>
  );
}

export const contribution = SheetBody.fill({ order: -10, Component: ({ sheetId }) => <Header sheetId={sheetId} /> });
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSingleFlight } from '../../query/useSingleFlight';
import { SheetBody } from '../../slots/defs/sheetBody';
import { useSheetToday, type SheetToday } from './useSheetToday';

/** The sheet's today, shown and changeable, and whether it is archived, with the steward's archive
 *  button. Changing today re-reads the whole sheet, since every date decision in it depends on today.
 *  Both share the one sheet error: the last of them refused. */
function TodayControl({ sheetId }: { sheetId: string }) {
  const today = useSheetToday(sheetId);
  const [date, setDate] = useState('');
  const queryClient = useQueryClient();
  const submitOnce = useSingleFlight();
  const save = useMutation({
    mutationFn: (raw: string) =>
      postJson<SheetToday>(`/api/sheets/${encodeURIComponent(sheetId)}/today`, { date: raw.trim() }),
    onSuccess: (sheet) => {
      queryClient.setQueryData(['sheet', sheetId, 'today'], sheet);
      void queryClient.invalidateQueries({
        queryKey: ['sheet', sheetId],
        predicate: (q) => q.queryKey[2] !== 'today',
      });
    },
  });
  const archive = useMutation({
    mutationFn: () => postJson<SheetToday>(`/api/sheets/${encodeURIComponent(sheetId)}/archive`, {}),
    onSuccess: (sheet) => queryClient.setQueryData(['sheet', sheetId, 'today'], sheet),
  });
  const error = save.error ?? archive.error;

  return (
    <form
      data-testid="sheet-today-form"
      onSubmit={(e) => {
        e.preventDefault();
        submitOnce(() => {
          save.reset();
          archive.reset();
          return save.mutateAsync(date);
        });
      }}
    >
      Today: <strong data-testid="sheet-today">{today.data?.today ?? ''}</strong>{' '}
      <label>
        Set today{' '}
        <input
          type="text"
          placeholder="yyyy-mm-dd"
          data-testid="sheet-today-input"
          value={date}
          onChange={(e) => {
            setDate(e.target.value);
            save.reset();
            archive.reset();
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="sheet-today-save" disabled={save.isPending}>
        Set
      </button>
      Archived: <strong data-testid="sheet-archived">{today.data ? (today.data.archived ? 'yes' : 'no') : ''}</strong>{' '}
      <button
        type="button"
        data-testid="sheet-archive"
        disabled={archive.isPending}
        onClick={() =>
          submitOnce(() => {
            save.reset();
            archive.reset();
            return archive.mutateAsync();
          })
        }
      >
        Archive sheet
      </button>
      {error && <p data-testid="sheet-error">{error.message}</p>}
    </form>
  );
}

export const contribution = SheetBody.fill({
  order: 0,
  Component: ({ sheetId }) => <TodayControl sheetId={sheetId} />,
});

